<?php require_once 'config.php';require_once 'lang.php';$langue=$_COOKIE['langue']??'fr';$titre_page=t('titre_salaires');$r=$connexion->query('SELECT * FROM employes ORDER BY salaire DESC');$a=[];$total=0;$sum=0;$max=0;while($e=$r->fetch_assoc()){$a[]=$e;$total++;$sum+=(float)$e['salaire'];$max=max($max,(float)$e['salaire']);}include 'inclure_entete.php';?><header><h1><?=t('titre_salaires')?></h1></header><section class="stats"><div><?=number_format($sum,0,',',' ')?> Ar<br><?=t('masse_salariale')?></div><div><?=number_format($total? $sum/$total:0,0,',',' ')?> Ar<br><?=t('salaire_moyen')?></div><div><?=number_format($max,0,',',' ')?> Ar<br><?=t('salaire_plus_haut')?></div></section><section class="carte"><table><tr><th><?=t('col_employe')?></th><th><?=t('col_salaire')?></th></tr><?php foreach($a as $e):?><tr><td><?=htmlspecialchars($e['prenom'].' '.$e['nom'])?></td><td><?=number_format($e['salaire'],2,',',' ')?></td></tr><?php endforeach;?></table></section><?php include 'inclure_pied.php';?>
